/// Every calculation in the registry, sorted by id.
static ALL_SPECS: &[&CalcSpec] = &[
    &CONDUCTION_PLANE_WALL_SPEC,
    &LMTD_CORRECTION_FACTOR_SPEC,
    &SHELL_AND_TUBE_RATING_SPEC,
    &SHELL_AND_TUBE_VIBRATION_SPEC,
];

/// All specs, in a stable order.
#[must_use]
pub fn specs() -> &'static [&'static CalcSpec] {
    ALL_SPECS
}

/// Look up a spec by id.
#[must_use]
pub fn spec(id: &str) -> Option<&'static CalcSpec> {
    ALL_SPECS.iter().copied().find(|s| s.id == id)
}
